import itertools
from matplotlib import pylab as plt
from scipy import stats
import ase.units as un
import numpy as np
from ase.build import bulk
from tqdm.auto import tqdm

# from rich.progress import track

flatten = itertools.chain.from_iterable

def plan_T_scan(Tlo, Thi, nat, N=1, plot_dist=True):
    l = Tlo
    n = np.sqrt(3 * nat / 2 / 2)  # 1/sqrt(2) adjusts for the shape of the distribution 
    s0 = l / n  # generated by the HECSS.smple function.
    s = s0
    assert n > 1
    a = (n + 1) / (n - 1)
    r = []
    while l <= Thi:
        sf = s
        if l * a > Thi:
            sf *= 1.12
        r.append([l, s, sf / s0])
        l *= a
        s = l / n
    ns = 1
    frm = 'N=%.1f'
    if N > 1:
        ns = N / r[-1][-1]
        frm = 'N=%.0f'
        r = [[l, s, int(round(ns * sf))] for l, s, sf in r]
    frm += ' T=%.0fK'
    if plot_dist:
        f = stats.norm.pdf
        x = np.linspace(Tlo * (1 - 3 / n), Thi * (1 + 3 / n), 600)
        y = np.zeros(x.shape)
        for c, (l, s, sf) in enumerate(r):
            p = sf * f(x, l, s)
            plt.plot(x, p, label=frm % (sf, l))
            y += p
        plt.plot(x, y)
        plt.legend(loc='upper right')  # plt.axvline(l-l/n, ymax=0.5, lw=1, ls='-', color=f'C{c}')
        plt.xlabel('Temperature')  # plt.axvline(l+l/n, ymin=0.5, lw=1, ls='-', color=f'C{c}')
        plt.ylabel('Relative density')  #f'N={sf*ns:.1f} T={l:.0f}K'
        plt.title('Temperature scan. N=relative number of samples')
    return r
